+  transform: translateY(-140%);
+  transition: transform var(--dur) var(--ease);
+  z-index: 1000;
+}
+
+.skip-link:focus {
+  transform: translateY(0);
+  outline: none;
+}
+
+.section {
+  padding: 92px 0;
+}
+
+.section-head {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 20px;
+  margin-bottom: 28px;
+}
+
+.section-actions {
+  display: flex;
+  gap: 10px;
+}
+
+.section-title {
+  margin: 0;
+  font-size: clamp(28px, 2.4vw, 40px);
+  letter-spacing: -0.03em;
+}
+
+.section-subtitle {
+  margin: 10px 0 0;
+  color: var(--muted);
+  max-width: 68ch;
+}
+
+.body {
+  margin: 14px 0 0;
+  color: var(--muted);
+}
+
+.eyebrow {
+  margin: 0 0 14px;
+  color: rgba(255, 255, 255, 0.82);
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  font-size: 12px;
+}
+
+.pill {
+  display: inline-flex;
+  padding: 4px 10px;
+  border-radius: 999px;
+  border: 1px solid var(--stroke);
